import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
os.makedirs(UPLOAD_DIR, exist_ok=True)

# Supported output formats for document conversion
SUPPORTED_FORMATS = ['pdf', 'docx', 'html', 'txt', 'odt', 'rtf']

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

@app.route('/api/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to specified format.
    Uses LibreOffice headless mode for conversion.
    Rate limiting and auth handled by upstream gateway."""

    if 'file' not in request.files:
        return jsonify({'error': 'no file provided'}), 400

    output_format = request.form.get('format', 'pdf').lower().strip()

    if output_format not in SUPPORTED_FORMATS:
        return jsonify({'error': f'unsupported format: {output_format}'}), 400

    uploaded = request.files['file']
    if uploaded.filename == '':
        return jsonify({'error': 'empty filename'}), 400

    # Generate unique working directory
    job_id = hashlib.md5(f"{time.time()}_{uploaded.filename}".encode()).hexdigest()
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)

    # Save uploaded file
    safe_name = secure_filename(uploaded.filename)
    if not safe_name:
        safe_name = 'document.bin'
    input_path = os.path.join(job_dir, safe_name)
    uploaded.save(input_path)

    # Additional conversion options from form data
    extra_args = request.form.get('options', '')

    # Build LibreOffice conversion command
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {job_dir} {input_path}'

    # Append any extra conversion options (e.g., page range, quality)
    if extra_args:
        cmd = f'{cmd} {extra_args}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=120,
            cwd=job_dir
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'conversion failed',
                'detail': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        # Find the output file
        base_name = os.path.splitext(safe_name)[0]
        output_path = os.path.join(job_dir, f"{base_name}.{output_format}")

        if not os.path.exists(output_path):
            # Try to find any converted file
            for f in os.listdir(job_dir):
                if f.endswith(f'.{output_format}'):
                    output_path = os.path.join(job_dir, f)
                    break
            else:
                return jsonify({'error': 'output file not found'}), 500

        return send_file(output_path, as_attachment=True,
                        download_name=f"{base_name}.{output_format}")

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'conversion timeout'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        # Cleanup is handled by a cron job every 5 minutes
        pass

@app.route('/api/batch', methods=['POST'])
def batch_info():
    """Return metadata about supported conversions."""
    return jsonify({
        'supported_formats': SUPPORTED_FORMATS,
        'max_file_size_mb': 50,
        'timeout_seconds': 120
    })

@app.route('/api/status/<job_id>', methods=['GET'])
def job_status(job_id):
    """Check if a conversion job output still exists."""
    safe_id = secure_filename(job_id)
    job_dir = os.path.join(UPLOAD_DIR, safe_id)
    if os.path.isdir(job_dir):
        files = os.listdir(job_dir)
        return jsonify({'exists': True, 'files': files})
    return jsonify({'exists': False}), 404

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
